def find_least_num_of_unique_ints(arr, k):
    freq = {}
    for v in arr:
        freq[v] = freq.get(v, 0) + 1

    values = list(freq.keys())
    remaining = k
    while remaining > 0:
        min_val = min(values, key=lambda v: freq[v])
        freq[min_val] -= 1
        remaining -= 1
        if freq[min_val] == 0:
            values.remove(min_val)

    return len(values)


if __name__ == "__main__":
    print(find_least_num_of_unique_ints([5, 5, 4], 1))
    print(find_least_num_of_unique_ints([4, 3, 1, 1, 3, 3, 2], 3))

