import java.util.*;

public class Main {
    static int findLeastNumOfUniqueInts(int[] arr, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : arr) freq.merge(v, 1, Integer::sum);

        for (int step = 0; step < k; step++) {
            int minKey = -1, minVal = Integer.MAX_VALUE;
            for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
                if (e.getValue() < minVal) { minVal = e.getValue(); minKey = e.getKey(); }
            }
            freq.put(minKey, freq.get(minKey) - 1);
            if (freq.get(minKey) == 0) freq.remove(minKey);
        }
        return freq.size();
    }

    public static void main(String[] args) {
        System.out.println(findLeastNumOfUniqueInts(new int[]{5, 5, 4}, 1));
        System.out.println(findLeastNumOfUniqueInts(new int[]{4, 3, 1, 1, 3, 3, 2}, 3));
    }
}

