#include <bits/stdc++.h>
using namespace std;

int findLeastNumOfUniqueInts(vector<int>& arr, int k) {
    unordered_map<int, int> freq;
    for (int v : arr) freq[v]++;

    for (int step = 0; step < k; step++) {
        int minKey = -1, minVal = INT_MAX;
        for (auto& [key, val] : freq) {
            if (val < minVal) { minVal = val; minKey = key; }
        }
        freq[minKey]--;
        if (freq[minKey] == 0) freq.erase(minKey);
    }
    return freq.size();
}

int main() {
    vector<int> arr1 = {5, 5, 4};
    cout << findLeastNumOfUniqueInts(arr1, 1) << endl;
    vector<int> arr2 = {4, 3, 1, 1, 3, 3, 2};
    cout << findLeastNumOfUniqueInts(arr2, 3) << endl;
    return 0;
}

