#include <bits/stdc++.h>
using namespace std;

int findLeastNumOfUniqueInts(vector<int>& arr, int k) {
    unordered_map<int, int> freq;
    for (int v : arr) freq[v]++;

    vector<int> counts;
    for (auto& [key, val] : freq) counts.push_back(val);
    sort(counts.begin(), counts.end());
    int unique = counts.size();

    for (int c : counts) {
        if (k >= c) {
            k -= c;
            unique--;
        } else {
            break;
        }
    }
    return unique;
}

